export function verifyDelivery(raw: string, sig: string): Delivery {
  const parsed = parseSignature(sig);
  assertFresh(parsed.timestamp);
  return { id: parsed.deliveryId, eventId: parsed.eventId, body: raw };
}

export function seen(store: Store, d: Delivery): boolean {
  const key = `evt:${d.eventId}`;
  if (store.has(key)) return true;
  store.put(key, Date.now());
  return false;
}

export async function withRetry(fn: Handler, d: Delivery) {
  for (const wait of BACKOFF) {
    try { return await fn(d); } catch { await sleep(wait); }
  }
  return fn(d);
}

export async function withRetry(fn: Handler, d: Delivery) {
  for (const wait of [...BACKOFF, 0]) {
    try { return await fn(d); } catch { await sleep(wait); }
  }
}

export function seen(store: Store, d: Delivery): boolean {
  const key = `dlv:${d.id}`;
  if (store.has(key)) return true;
  store.put(key, Date.now());
  return false;
}
